package org.sleepwell.app;
import android.content.Context;import org.json.*;import java.util.*;
/** Deliberately bounded typed settings, never a dump of private preferences. */
final class SettingsProfile {
 static final int LIMIT=65536;static final String[] CATEGORIES={"Appearance","Sleep plan","Bundled sounds","Narration"};
 final JSONObject appearance,plan,sounds,narration;
 SettingsProfile(JSONObject a,JSONObject p,JSONObject s,JSONObject n){appearance=a;plan=p;sounds=s;narration=n;}
 static void keys(JSONObject object,String... keys)throws JSONException{Set<String> expected=Set.of(keys);if(object.length()!=expected.size())throw new JSONException("Unsupported settings fields");for(String key:keys)if(!object.has(key))throw new JSONException("Missing settings field: "+key);}
 static int number(JSONObject row,String key,int low,int high)throws JSONException{long value=SensorProvenance.whole(row,key);if(value<low||value>high)throw new JSONException("Unsupported "+key);return (int)value;}
 static boolean flag(JSONObject row,String key)throws JSONException{Object value=row.get(key);if(!(value instanceof Boolean))throw new JSONException("Invalid "+key);return (Boolean)value;}
 static SettingsProfile capture(Context context,boolean[] include)throws JSONException{
  JSONObject a=null,p=null,s=null,n=null;
  if(include[0])a=new JSONObject().put("automatic",Appearance.automatic(context)).put("theme",Prefs.number(context,Appearance.THEME,0)).put("textSize",Prefs.number(context,Appearance.SIZE,0)).put("reduceMotion",Appearance.reduced(context)).put("highContrast",Appearance.contrast(context));
  if(include[1]){SleepPlan value=SleepPlans.load(context);value.validate();p=new JSONObject().put("goal",value.goal).put("bedtime",value.bedtime).put("wake",value.wake).put("windDown",value.windDown).put("reminderAdvance",value.reminderAdvance).put("repeatMinutes",value.smartRepeatMinutes).put("repeatLimit",value.smartRepeatLimit).put("reminder",value.reminder).put("smartBedtime",value.smartBedtime).put("noAlarmBedtime",value.noAlarmBedtime);}
  if(include[2]){SoundMix value=SoundPreferences.load(context);if(value.primary.equals("My audio")||value.primary.equals(SoundPlaylist.NAME))throw new IllegalArgumentException("Local audio and playlist document references cannot transfer. Choose a bundled source first, or deselect Bundled sounds before exporting.");s=new JSONObject().put("primary",value.primary).put("primaryGain",value.primaryGain).put("brownGain",value.brownGain).put("timerMinutes",value.timerMinutes).put("fadeMinutes",value.fadeMinutes).put("carrier",value.binauralCarrier).put("beat",value.binauralBeat).put("rotation",new JSONObject(value.rotation.encode())).put("withTracking",value.withTracking);}
  if(include[3]){NarrationSettings value=NarrationSettings.load(context);n=new JSONObject().put("rate",value.rate).put("pitch",value.pitch);}
  SettingsProfile profile=new SettingsProfile(a,p,s,n);decode(profile.encode());return profile;
 }
 String encode()throws JSONException{JSONObject categories=new JSONObject();if(appearance!=null)categories.put("appearance",appearance);if(plan!=null)categories.put("sleepPlan",plan);if(sounds!=null)categories.put("sounds",sounds);if(narration!=null)categories.put("narration",narration);return new JSONObject().put("format","sleepwell-settings-profile").put("version",1).put("categories",categories).toString(2);}
 static SettingsProfile decode(String text)throws JSONException{if(text==null||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>LIMIT)throw new JSONException("Settings profiles must fit within 64 KiB");JSONObject root=SettingsProfileJson.object(text);keys(root,"format","version","categories");if(!SensorProvenance.text(root,"format").equals("sleepwell-settings-profile")||SensorProvenance.whole(root,"version")!=1)throw new JSONException("Unsupported settings profile version");JSONObject categories=root.getJSONObject("categories");if(categories.length()<1||categories.length()>4)throw new JSONException("Choose at least one supported settings category");for(Iterator<String> iterator=categories.keys();iterator.hasNext();)if(!Set.of("appearance","sleepPlan","sounds","narration").contains(iterator.next()))throw new JSONException("This profile contains an unsupported settings category");SettingsProfile profile=new SettingsProfile(categories.has("appearance")?categories.getJSONObject("appearance"):null,categories.has("sleepPlan")?categories.getJSONObject("sleepPlan"):null,categories.has("sounds")?categories.getJSONObject("sounds"):null,categories.has("narration")?categories.getJSONObject("narration"):null);profile.validate();return profile;}
 private void validate()throws JSONException{
  if(appearance!=null){keys(appearance,"automatic","theme","textSize","reduceMotion","highContrast");flag(appearance,"automatic");number(appearance,"theme",0,2);number(appearance,"textSize",0,2);flag(appearance,"reduceMotion");flag(appearance,"highContrast");}
  if(plan!=null){keys(plan,"goal","bedtime","wake","windDown","reminderAdvance","repeatMinutes","repeatLimit","reminder","smartBedtime","noAlarmBedtime");sleepPlan();flag(plan,"reminder");flag(plan,"smartBedtime");flag(plan,"noAlarmBedtime");}
  if(sounds!=null){keys(sounds,"primary","primaryGain","brownGain","timerMinutes","fadeMinutes","carrier","beat","rotation","withTracking");soundMix();flag(sounds,"withTracking");}
  if(narration!=null){keys(narration,"rate","pitch");try{narrationSettings();}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}}
 }
 SleepPlan sleepPlan()throws JSONException{SleepPlan value=new SleepPlan();value.goal=number(plan,"goal",20,810);value.bedtime=number(plan,"bedtime",0,1439);value.wake=number(plan,"wake",0,1439);value.windDown=number(plan,"windDown",0,120);value.reminderAdvance=number(plan,"reminderAdvance",0,120);value.smartRepeatMinutes=number(plan,"repeatMinutes",0,60);value.smartRepeatLimit=number(plan,"repeatLimit",1,12);try{value.validate();}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}value.reminder=false;value.smartBedtime=false;value.noAlarmBedtime=false;return value;}
 SoundMix soundMix()throws JSONException{SoundMix value=new SoundMix();value.primary=SensorProvenance.text(sounds,"primary");if(value.primary.equals("My audio")||value.primary.equals(SoundPlaylist.NAME))throw new JSONException("Local audio/playlist references are unsupported");value.primaryGain=number(sounds,"primaryGain",0,100);value.brownGain=number(sounds,"brownGain",0,100);value.timerMinutes=number(sounds,"timerMinutes",1,240);value.fadeMinutes=number(sounds,"fadeMinutes",0,240);value.binauralCarrier=number(sounds,"carrier",1,20000);value.binauralBeat=number(sounds,"beat",1,100);try{value.rotation=AmbientRotation.read(sounds.getJSONObject("rotation").toString());value.validate();}catch(IllegalArgumentException invalid){throw new JSONException(invalid.getMessage());}value.withTracking=false;return value;}
 NarrationSettings narrationSettings()throws JSONException{return new NarrationSettings(number(narration,"rate",75,115),number(narration,"pitch",85,115));}
 List<String> review(Context context)throws JSONException{List<String> rows=new ArrayList<>();if(appearance!=null)rows.add("Appearance · "+(flag(appearance,"automatic")?"Automatic light phases; manual fallback "+AppearancePolicy.THEMES[number(appearance,"theme",0,2)]:AppearancePolicy.THEMES[number(appearance,"theme",0,2)])+" · "+AppearancePolicy.SIZES[number(appearance,"textSize",0,2)]+" · reduced motion "+(flag(appearance,"reduceMotion")?"on":"off")+" · contrast "+(flag(appearance,"highContrast")?"high":"standard"));if(plan!=null){SleepPlan value=sleepPlan();rows.add("Sleep plan · goal "+PlanActivity.duration(value.goal)+" · bed "+Design.clock(context,value.bedtime)+" · wake "+Design.clock(context,value.wake)+" · wind-down "+value.windDown+" min · reminder advance "+value.reminderAdvance+" min · repeat "+value.smartRepeatMinutes+" min / "+value.smartRepeatLimit+". Source reminder "+(flag(plan,"reminder")?"on":"off")+", smart bedtime "+(flag(plan,"smartBedtime")?"on":"off")+", no-alarm reminder "+(flag(plan,"noAlarmBedtime")?"on":"off")+"; all three remain off after import.");}if(sounds!=null){SoundMix value=soundMix();rows.add("Bundled sounds · "+value.label()+" · primary "+value.primaryGain+"% / brown "+value.brownGain+"% · timer "+value.timerMinutes+" min · fade "+value.fadeMinutes+" min · stored rotation "+String.join(" → ",value.rotation.sounds)+" / "+value.rotation.minutes+" min · stored stereo carrier "+value.binauralCarrier+" Hz / beat "+value.binauralBeat+" Hz. Source Play with tracking "+(flag(sounds,"withTracking")?"on":"off")+"; it remains off after import.");}if(narration!=null){NarrationSettings value=narrationSettings();rows.add("Narration · "+value.rateLabel()+" · "+value.pitchLabel()+". Voice/provider selection is excluded; nothing is spoken.");}return rows;}
}
